1	//! JSON Schema strict-mode normalization.
2	//!
3	//! [`strict`] rewrites a schemars-produced JSON Schema to satisfy
4	//! **OpenAI strict-mode / JSON-Schema** requirements:
5	//! 1. `additionalProperties: false` on every object.
6	//! 2. Every key in each object's `properties` promoted into `required`
7	//!    (no truly-optional fields — `Option<T>` must use `"type": ["T", "null"]`
8	//!    and stay present in `required`; schemars 1.x emits this natively).
9	//!
10	//! This is **not** a provider-neutral transform: it encodes OpenAI's
11	//! strict-mode quirks. Per-provider normalization for future providers
12	//! (Bedrock/Gemini, untagged-enum collapsing) is a separate concern.
13	//! The OpenAI provider calls this; Anthropic uses schemas as-is.
14	
15	use serde_json::Value;
16	
17	/// Rewrite a JSON Schema for OpenAI strict-mode structured output.
18	///
19	/// Recursively sets `additionalProperties: false` on every object,
20	/// promotes every key in each object's `properties` into `required`, and
21	/// recurses into object `properties` and array `items`. Schemas that
22	/// would produce strict-mode rejections (hand-authored
23	/// `oneOf: [_, {type: "null"}]`, unsupported `pattern`, etc.) pass
24	/// through unmodified.
25	///
26	/// **Limitation:** `$defs`/`$ref` are not traversed. schemars 1.x emits
27	/// `$defs` for enums, recursive types, and types referenced more than once;
28	/// object schemas nested under `$defs` therefore do not receive
29	/// `additionalProperties: false` or the `required` promotion. Adequate for
30	/// flat/nested struct outputs; revisit if `$defs`-bearing schemas need strict
31	/// mode.
32	pub fn strict(value: &Value) -> Value {
33	    let mut out = value.clone();
34	    rewrite_in_place(&mut out);
35	    out
36	}
37	
38	fn rewrite_in_place(v: &mut Value) {
39	    if let Some(obj) = v.as_object_mut() {
40	        let is_object_schema = obj
41	            .get("type")
42	            .and_then(|t| t.as_str())
43	            .map(|s| s == "object")
44	            .unwrap_or(false);
45	
46	        if is_object_schema {
47	            obj.insert("additionalProperties".to_owned(), Value::Bool(false));
48	
49	            if let Some(props) = obj.get("properties").and_then(|p| p.as_object()) {
50	                let keys: Vec<String> = props.keys().cloned().collect();
51	                let required = Value::Array(keys.into_iter().map(Value::String).collect());
52	                obj.insert("required".to_owned(), required);
53	            }
54	        }
55	
56	        if let Some(props) = obj.get_mut("properties").and_then(|p| p.as_object_mut()) {
57	            for (_, child) in props.iter_mut() {
58	                rewrite_in_place(child);
59	            }
60	        }
61	        if let Some(items) = obj.get_mut("items") {
62	            rewrite_in_place(items);
63	        }
64	    }
65	}
